pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz parameters: an attacker address and an amount to deposit
    function testFuzz_property(address attacker, uint256 deposit) public {
        // keep deposit in a reasonable wide range but avoid zero to make effect visible
        deposit = bound(deposit, 1, 1 ether);
        // ensure attacker is not the owner (owner is address(this) because setUp deployed C)
        vm.assume(attacker != address(this));

        // fund attacker so they can send deposit to contract
        vm.deal(attacker, deposit);

        // attacker sends deposit to contract (via fallback payable)
        vm.prank(attacker);
        (bool sent, ) = address(c).call{value: deposit}("");
        require(sent, "deposit failed");

        // record balance after deposit
        uint256 balAfterDeposit = address(c).balance;

        // attacker attempts to call withdrawAll
        vm.prank(attacker);
        bool ok;
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // SINGLE ASSERT: in the correct contract, non-owner callers cannot withdraw funds,
        // so after a non-owner call to withdrawAll the contract balance remains equal to balAfterDeposit.
        // The mutant that removed onlyOwner will allow some attacker inputs to change the balance,
        // causing this assertion to fail for those inputs.
        assertTrue(address(c).balance == balAfterDeposit);
    }
}

