pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz: deposit amount and caller address
    function testFuzz_property(address caller, uint256 depositAmount) public {
        // keep domain wide but sensible: depositAmount fits in balance and nonzero
        depositAmount = bound(depositAmount, 0, 1 ether);

        // ensure caller is not the owner (owner is address(this) since setUp deployed c)
        // if fuzz gives the deployer, we still allow that case; the property must hold for ALL inputs
        // but to allow discovery of mutant we want some non-owner callers too; do not over-constrain

        // Fund the caller so they can send ether to c
        vm.deal(caller, depositAmount + 1);

        // Make a deposit by sending ETH to c (fallback increments depositsCount and increases balance)
        if (depositAmount > 0) {
            vm.prank(caller);
            (bool ok, ) = address(c).call{value: depositAmount}("");
            require(ok);
        }

        uint256 before = address(c).balance;

        // Try to have the caller call withdrawAll
        bool success;
        vm.prank(caller);
        try c.withdrawAll() {
            success = true;
        } catch {
            success = false;
        }

        uint256 after = address(c).balance;

        // General rule: if the caller is not the deployer/owner, calling withdrawAll must not reduce contract balance.
        // We express that as a single assertion the reference satisfies for ALL inputs and the mutant violates for some.
        address owner = address(this); // deployer of c in setUp
        if (caller != owner) {
            assertTrue(after >= before);
        } else {
            // if caller is owner, withdrawAll may drain funds; but still the invariant that balance is non-negative holds
            assertTrue(after <= before || after == before);
        }
    }
}

