pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address owner;

    function setUp() public { c = new C(); owner = address(this); }

    // fuzzed params: a nonOwner address and a deposit amount
    function testFuzz_property(address caller, uint256 amount) public {
        // keep caller from being the owner we deployed C from
        vm.assume(caller != address(0));
        vm.assume(caller != address(this));
        // bound amount to a reasonable range so vm.deal works
        amount = bound(amount, 1, 1 ether);

        // fund the contract by sending Ether to its fallback via an owner-prank
        vm.deal(address(this), amount);
        // send ETH to contract by calling fallback (no data)
        (bool sent,) = address(c).call{value: amount}("");
        require(sent);

        uint256 beforeBalance = address(c).balance;
        // ensure deposit happened
        require(beforeBalance == amount);

        // now have caller attempt to call withdrawAll (non-owner). If caller is not owner,
        // in the reference contract this must NOT reduce address(c).balance; the mutant may
        // allow it. We track whether the call succeeded and then assert the invariant on balance.

        vm.deal(caller, 1 ether);
        vm.prank(caller);
        bool ok;
        try c.withdrawAll{gas: gasleft()}() {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: after any caller (possibly non-owner) calls withdrawAll, the contract's balance remains unchanged unless the caller is the owner. We read address(c).balance to observe this.
        // For our test we require caller != owner, so reference should always preserve balance.
        assertTrue(caller == address(this) || address(c).balance == beforeBalance);
    }
}

