contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: depositor (who funds the contract), caller (who calls withdrawAll), and amount
    function testFuzz_property(address depositor, address caller, uint256 amount) public {
        // keep addresses realistic: non-zero
        vm.assume(depositor != address(0));
        vm.assume(caller != address(0));
        // keep amount in a reasonable range but wide
        amount = bound(amount, 1, 1 ether);

        // depositor funds the contract
