            // call reverted
        }

        uint256 after = address(c).balance;

        // General rule: if caller is NOT the owner, the contract balance must remain unchanged (only owner may withdrawAll)
        // This holds for the reference contract; the mutant that removes onlyOwner will allow some non-owner caller to reduce the balance.
