pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the amount of ether initially sent to the contract
    function testFuzz_property(uint256 initialFund) public {
        // keep domain wide but reasonable for fund size
        initialFund = bound(initialFund, 1, 1 ether);

        // fund an external EOA (the owner is the test contract's deployer, setUp created c from this address)
        // ensure the contract has initialFund balance by sending from this test contract (owner)
        vm.deal(address(this), initialFund);
        // send funds into c via fallback by calling with value from owner
        c.fallback{value: initialFund}();

        // record balances before withdrawAll
        uint256 beforeContract = address(c).balance;
        uint256 beforeOwner = address(this).balance;

        // call withdrawAll as owner (this contract deployed c in setUp)
        bool ok;
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // After successful call, reference contract transfers entire contract balance to owner.
        // So if the call succeeded, contract balance must be zero and owner's balance must have increased by beforeContract.
        // We assert the universal property: whenever withdrawAll returns (no revert) the contract balance is zero.
